  const proxyUrl = request.nextUrl.clone()
  proxyUrl.pathname =
    `/api/v0-preview/${chatId}${request.nextUrl.pathname}`

  return NextResponse.redirect(proxyUrl, 307)
}

export const config = {
  matcher: '/((?!api/v0-preview/).*)',
}

